export function sanitizeInput(input: string): string {
  const replacements: Array<[RegExp, string]> = [
    [/</g, '&lt;'],
    [/>/g, '&gt;'],
    [/"/g, '&quot;'],
    [/'/g, '&#039;']
  ];

  return replacements.reduce(
    (result, [pattern, replacement]) => result.replace(pattern, replacement),
    input
  );
}

